  "cplx-01-loop-triangular":{category:"algorithmic-complexity",title:"Count the Loops, Name the Growth",objective:[["obj-1","`node instrumented.js` runs without throwing and prints exactly 5 lines in the exact form 'n=<n> steps=<count>' for n=1,5,10,50,100 in that order"],["obj-2","The 5 printed step counts equal the answer key 1, 15, 55, 1275, 5050 respectively (judge recomputes n(n+1)/2 independently; a model that instruments n^2 instead prints 1, 25, 100, 2500, 10000 and fails)"],["obj-3","`module.exports.stepCost(20)` returns 210 via `node -e` (judge-chosen unlisted value; catches implementations that hardcode the 5 printed cases instead of computing generally)"],["obj-4","ANALYSIS.md states the exact closed form n(n+1)/2 (or the algebraically equal n^2/2 + n/2) AND the asymptotic class Theta(n^2); naming only Theta(n^2) without the exact triangular formula fails this check"],["obj-5","ANALYSIS.md is at most 200 words (whole file, `wc -w`)"]],subjective:[["sub-quality","Analytical precision",0.4],["sub-craft","Instrumentation clarity",0.3],["sub-reasoning","Reasoning quality",0.3]],weights:{objective:0.7,subjective:0.3}},
  "cplx-01b-pairwise-collation":{category:"algorithmic-complexity",title:"Collate the Witnesses, Name the Growth",objective:[["obj-1","`node instrumented.js` runs without throwing and prints exactly 5 lines in the exact form 'n=<n> comparisons=<count>' for n=3,6,15,45,90 in that order"],["obj-2","The 5 printed comparison counts equal the answer key 3, 15, 105, 990, 4005 respectively (judge recomputes n(n-1)/2 independently; a model that instruments a full n^2 grid instead prints 9, 36, 225, 2025, 8100 and fails)"],["obj-3","`module.exports.collationCost(30)` returns 435 via `node -e` (judge-chosen unlisted value; catches implementations that hardcode the 5 printed cases instead of computing generally)"],["obj-4","ANALYSIS.md states the exact closed form n(n-1)/2 (or the algebraically equal n^2/2 - n/2) AND the asymptotic class Theta(n^2); naming only Theta(n^2) without the exact pairwise formula fails this check"],["obj-5","ANALYSIS.md is at most 200 words (whole file, `wc -w`)"]],subjective:[["sub-quality","Analytical precision",0.4],["sub-craft","Instrumentation clarity",0.3],["sub-reasoning","Reasoning quality",0.3]],weights:{objective:0.7,subjective:0.3}},
