  "data-06-alert-base-rates":{category:"data-analysis",title:"Base rates behind a fraud alert",objective:[["obj-1","Confusion matrix for 100,000 transactions is correct: TP=460, FN=40, FP=4975, TN=94525"],["obj-2","Positive predictive value (PPV) is reported as approximately 8.5% (accept 8.0%-9.0%)"],["obj-3","Verdict rejects 'auto-block every alert' and explains most alerts are false positives because fraud is rare (base-rate neglect) — prose-located check; PASS phrasings include 'only ~8.5% of alerts are real fraud; auto-blocking would wrongly block ~4,975 legitimate transactions' or 'the base rate is so low that most flags are false alarms, don't auto-block'; FAIL phrasings include 'the model is 92% accurate so alerts are trustworthy, auto-block' or 'high accuracy means block on alert' or '95% specificity means we're safe to auto-block'"],["obj-4","The number of legitimate transactions wrongly blocked under auto-block is stated as 4,975 (the FP count)"],["obj-5","TRIAGE.md is at most 450 words, whole file, wc -w"]],subjective:[["sub-quality","Base-rate reasoning correctness",0.4],["sub-craft","Decision framing for operators",0.3],["sub-reasoning","Reasoning quality",0.3]],weights:{objective:0.7,subjective:0.3}},
  "data-06b-leak-alert-base-rates":{category:"data-analysis",title:"Base rates behind a leak alert",objective:[["obj-1","Confusion matrix for 80,000 segments is correct: TP=540, FN=60, FP=4764, TN=74636"],["obj-2","Positive predictive value (PPV) is reported as approximately 10.2% (accept 9.5%-11.0%)"],["obj-3","Verdict rejects 'auto-dispatch on every alert' and explains most alerts are false positives because leaks are rare (base-rate neglect) — prose-located check; PASS phrasings include 'only ~10% of alerts are real leaks; auto-dispatching would needlessly excavate ~4,764 sound segments' or 'the leak prevalence is so low that most flags are false alarms, don't auto-dig' or 'about 1 in 10 alerts is a true leak, so confirm before sending a crew'; FAIL phrasings include 'the classifier is 90% accurate so alerts are trustworthy, auto-dispatch' or 'high accuracy means dig on every alert' or '94% specificity means we're safe to auto-excavate'"],["obj-4","The number of sound segments needlessly excavated under auto-dispatch is stated as 4,764 (the FP count)"],["obj-5","TRIAGE.md is at most 450 words, whole file, wc -w"]],subjective:[["sub-quality","Base-rate reasoning correctness",0.4],["sub-craft","Decision framing for operators",0.3],["sub-reasoning","Reasoning quality",0.3]],weights:{objective:0.7,subjective:0.3}},
  "data-06c-weld-scan-base-rates":{category:"data-analysis",title:"Base rates behind a weld-scan flag",objective:[["obj-1","Confusion matrix for 50,000 welds is correct: TP=264, FN=36, FP=3479, TN=46221"],["obj-2","Positive predictive value (PPV) is reported as approximately 7.1% (accept 6.6%-7.5%)"],["obj-3","Verdict rejects 'auto-scrap every flag' and explains most flags are false positives because real defects are rare (base-rate neglect) — prose-located check; PASS phrasings include 'only ~7.1% of flags are real defects; auto-scrapping would wrongly destroy ~3,479 sound welds' or 'the base rate is so low that most flags are false alarms, don't auto-scrap'; FAIL phrasings include 'the scanner is 88% accurate so flags are trustworthy, auto-scrap' or 'high accuracy means scrap on flag' or '93% specificity means we're safe to auto-scrap'"],["obj-4","The number of sound welds wrongly scrapped under auto-scrap is stated as 3,479 (the FP count)"],["obj-5","TRIAGE.md is at most 450 words, whole file, wc -w"]],subjective:[["sub-quality","Base-rate reasoning correctness",0.4],["sub-craft","Decision framing for operators",0.3],["sub-reasoning","Reasoning quality",0.3]],weights:{objective:0.7,subjective:0.3}},
