  "data-09-audit-script":{category:"data-analysis",title:"Auditing the analyst's stats script",objective:[["obj-1","The lexicographic-median bug is identified: AUDIT.md states the script's median is 4.5 (wrong) and the correct numeric-sort median is 7.5"],["obj-2","The conversion-denominator bug is identified: AUDIT.md states the script yields approximately 17.6% (30/170) and the correct rate is 15.0% (30/200)"],["obj-3","fixed.js runs with `node fixed.js` and its printed median equals 7.5 and its printed conversion rate equals 15% (accept '15', '15.0', '15%', '15.0%', or '0.15')"],["obj-4","All three seeded bugs are enumerated distinctly (median sort, conversion denominator, and the mislabeled/typo average 15.6 whose value differs from the true mean 16.5) rather than lumped as one vague note (prose-located)"],["obj-5","AUDIT.md is at most 450 words, whole file, wc -w"]],subjective:[["sub-quality","Diagnostic accuracy",0.4],["sub-craft","Fix quality and audit-trail clarity",0.3],["sub-reasoning","Reasoning quality",0.3]],weights:{objective:0.7,subjective:0.3}},
