  "debug-08-cache-leak-from-logs":{category:"debugging",title:"Diagnose a cache leak from telemetry alone",objective:[["obj-1","DIAGNOSIS.md identifies that the cache key includes the volatile timestamp field, making every key unique and the hit rate effectively 0% -- naming this field specifically"],["obj-2","DIAGNOSIS.md identifies the second contributing cause: eviction runs only from inside the cache-hit branch, so with ~0% hits it never executes and the cache grows unbounded"],["obj-3","DIAGNOSIS.md cites the specific telemetry signal that confirms the leak (monotonically rising cache_entries / rss_mb under flat req_rate_per_s) and does NOT attribute the leak to the decoy gc_pause_ms sawtooth metric"],["obj-4","node fix.js runs a self-test showing that after 100 distinct requests (differing only in timestamp) the cache holds at most 50 entries, and that two requests identical except for timestamp produce a cache hit / a single stored entry"],["obj-5","fix.js is at most 90 lines, plain JavaScript, no dependencies, and keys the cache without the volatile timestamp field"]],subjective:[["sub-quality","Telemetry inference",0.4],["sub-craft","Fix completeness",0.3],["sub-reasoning","Reasoning quality",0.3]],weights:{objective:0.5,subjective:0.5}},
  "debug-08b-geocode-cache-leak":{category:"debugging",title:"Diagnose a geocoder cache leak from telemetry alone",objective:[["obj-1","DIAGNOSIS.md identifies that the cache key includes the volatile traceId field, making every key unique and the hit rate effectively 0% -- naming this field specifically"],["obj-2","DIAGNOSIS.md identifies the second contributing cause: eviction (trimIfFull) runs only from inside the cache-hit branch, so with ~0% hits it never executes and the cache grows unbounded"],["obj-3","DIAGNOSIS.md cites the specific telemetry signal that confirms the leak (monotonically rising lookup_cache_entries / heap_used_mb under flat lookups_per_s) and does NOT attribute the leak to the decoy compaction_ms sawtooth metric"],["obj-4","node fix.js runs a self-test showing that after 120 distinct requests (differing only in traceId) the cache holds at most 64 entries, and that two requests identical except for traceId produce a cache hit / a single stored entry"],["obj-5","fix.js is at most 90 lines, plain JavaScript, no dependencies, and keys the cache without the volatile traceId field"]],subjective:[["sub-quality","Telemetry inference",0.4],["sub-craft","Fix completeness",0.3],["sub-reasoning","Reasoning quality",0.3]],weights:{objective:0.5,subjective:0.5}},
  "debug-08c-permit-memo-leak":{category:"debugging",title:"Diagnose a permit-cache leak from telemetry alone",objective:[["obj-1","DIAGNOSIS.md identifies that the memo key includes the volatile sessionId field, making every key unique and the hit rate effectively 0% -- naming this field specifically"],["obj-2","DIAGNOSIS.md identifies the second contributing cause: pruning runs only from inside the memo-hit branch, so with ~0% hits it never executes and the memo grows unbounded"],["obj-3","DIAGNOSIS.md cites the specific telemetry signal that confirms the leak (monotonically rising memo_entries / heap_mb under flat submit_rate_per_s) and does NOT attribute the leak to the decoy flush_latency_ms sawtooth metric"],["obj-4","node fix.js runs a self-test showing that after 96 distinct requests (differing only in sessionId) the memo holds at most 72 entries, and that two requests identical except for sessionId produce a memo hit / a single stored entry"],["obj-5","fix.js is at most 90 lines, plain JavaScript, no dependencies, and keys the memo without the volatile sessionId field"]],subjective:[["sub-quality","Telemetry inference",0.4],["sub-craft","Fix completeness",0.3],["sub-reasoning","Reasoning quality",0.3]],weights:{objective:0.5,subjective:0.5}},
