  "game-03-balance-patch":{category:"game-design",title:"Balance patch for a squad-battler stat table",objective:[["obj-1","BALANCE.md contains a DPS table whose four values match the reference (Bulwark 13.5, Skirmisher 12.0, Longshot 12.6, Twinfang 18.7) within +/-0.1; judge recomputes damage x accuracy / interval for each unit"],["obj-2","Twinfang is explicitly identified as the overpowered/outlier unit (not Longshot)"],["obj-3","The proposed patch targets Twinfang and only Twinfang, changes at most two of its stats, every changed stat differs from its original value by at most 20% relative, and the judge-recomputed post-patch Twinfang DPS lies in [12.0, 14.0] (judge recomputes from the patched stat values; any patch satisfying all constraints passes, not only the sample below)"],["obj-4","BALANCE.md is at most 500 words (whole file, wc -w)"],["obj-5","BALANCE.md states the post-patch DPS as an explicit number and that number matches the judge's recomputation from the patched stats within +/-0.1"]],subjective:[["sub-quality","Balance analysis quality",0.4],["sub-craft","Patch design craft",0.3],["sub-reasoning","Reasoning quality",0.3]],weights:{objective:0.5,subjective:0.5}},
