  "game-04-puzzle-pack":{category:"game-design",title:"Simulator-verified puzzle level pack with a difficulty curve",objective:[["obj-1","Running the reference simulator (embedded verbatim below, identical to the test file) with 'node engine.js levels.json' prints PASS for all three levels (PASS requires: win reached, no illegal move, not pre-solved, no game state revisited during the replay)"],["obj-2","Move counts printed by the simulator satisfy the bands: Level 1 <= 12, Level 2 in [13, 25], Level 3 >= 26"],["obj-3","The simulator's printed level stats confirm: L1 exactly 1 crate and grid <= 8x8; L2 exactly 2 crates and grid <= 10x10; L3 >= 3 crates and grid <= 10x10; and each level has at least one crate starting off-target"],["obj-4","levels.json parses as valid JSON matching the schema (array of {name, grid, solution}) when loaded with node"],["obj-5","DESIGN.md is at most 600 words (whole file, wc -w)"]],subjective:[["sub-quality","Level design quality",0.4],["sub-craft","Difficulty curve and elegance",0.3],["sub-reasoning","Reasoning quality",0.3]],weights:{objective:0.5,subjective:0.5}},
