  "game-05-be-the-engine":{category:"game-design",title:"Adjudicate a duel turn log as the rules engine",objective:[["obj-1","final_state.json parses as valid JSON with node and equals exactly {\\\"NORTH\\\":{\\\"hp\\\":20,\\\"guard\\\":0},\\\"SOUTH\\\":{\\\"hp\\\":12,\\\"guard\\\":0}} (compare field-by-field, integer values)"],["obj-2","ADJUDICATION.md's stated per-turn HP totals after NORTH's third turn read SOUTH at 9 HP (the FOCUS+HEAVY = 9 damage step), demonstrating the FOCUS +2 bonus was applied"],["obj-3","ADJUDICATION.md explicitly identifies at least two cards from the log that were SKIPPED for insufficient energy (the third-turn trailing STRIKE and the fourth-turn second DRAIN)"],["obj-4","ADJUDICATION.md states that NORTH ends with 0 GUARD tokens because the final SOUTH STRIKE (6 damage after FOCUS) consumed both stacked tokens — the second token being consumed despite absorbing only 1 damage"],["obj-5","ADJUDICATION.md is at most 500 words (whole file, wc -w)"]],subjective:[["sub-quality","Adjudication accuracy and completeness",0.4],["sub-craft","Clarity of the turn-by-turn trace",0.3],["sub-reasoning","Reasoning quality",0.3]],weights:{objective:0.7,subjective:0.3}},
