  "game-05c-coilworks-arena":{category:"game-design",title:"Adjudicate a battlebot bout log as the rules engine",objective:[["obj-1","final_state.json parses as valid JSON with node and equals exactly {\\\"HAMMER\\\":{\\\"hull\\\":15,\\\"plate\\\":0},\\\"PIVOT\\\":{\\\"hull\\\":7,\\\"plate\\\":0}} (compare field-by-field, integer values)"],["obj-2","ADJUDICATION.md's stated per-turn HULL totals after HAMMER's third turn read PIVOT at 5 HULL (the PRIME+SLAM = 9 damage step), demonstrating the PRIME +3 bonus was applied"],["obj-3","ADJUDICATION.md explicitly identifies at least two cards from the log that were SKIPPED for insufficient power (the third-turn trailing SLAM and the fourth-turn second MEND)"],["obj-4","ADJUDICATION.md states that HAMMER ends with 0 PLATE tokens because the final PIVOT JAB (6 damage after PRIME) consumed both stacked tokens — the second token being consumed despite absorbing only 2 damage"],["obj-5","ADJUDICATION.md is at most 500 words (whole file, wc -w)"]],subjective:[["sub-quality","Adjudication accuracy and completeness",0.4],["sub-craft","Clarity of the turn-by-turn trace",0.3],["sub-reasoning","Reasoning quality",0.3]],weights:{objective:0.7,subjective:0.3}},
  "game-06-break-it":{category:"game-design",title:"Break the card set — find the seeded degenerate loop",objective:[["obj-1","BREAK.md identifies card C 'Emberpact' (by name or letter) as the degenerate/broken card"],["obj-2","BREAK.md states the loop is unbounded/infinite specifically because Emberpact costs 0 energy AND nets +1 energy per play with no once-per-turn/exhaust limiter — all three properties (cost 0, positive net energy, no limiter) must be cited"],["obj-3","BREAK.md shows the growth arithmetic explicitly: after k plays energy = starting + k and damage = 2k (or an equivalent per-play +1 energy / +2 damage framing with no ceiling)"],["obj-4","BREAK.md proposes a minimal fix that removes the degeneracy while keeping the card playable (exhaust/once-per-turn clause, cost raised to >=1, or a capped energy gain) and does NOT propose simply deleting the card or nerfing an unrelated card"],["obj-5","BREAK.md is at most 450 words (whole file, wc -w)"]],subjective:[["sub-quality","Depth of the design critique",0.4],["sub-craft","Rigor of the degeneracy proof",0.3],["sub-reasoning","Reasoning quality",0.3]],weights:{objective:0.5,subjective:0.5}},
  "game-06b-degenerate-sigil":{category:"game-design",title:"Break the rune set — find the seeded degenerate loop",objective:[["obj-1","BREAK.md identifies rune C 'Emberglass' (by name or letter) as the degenerate/broken rune"],["obj-2","BREAK.md states the loop is unbounded/infinite specifically because Emberglass costs 0 aether AND nets +1 aether per cast with no once-per-round/dissipate limiter — all three properties (cost 0, positive net aether, no limiter) must be cited"],["obj-3","BREAK.md shows the growth arithmetic explicitly: after k casts aether = starting + k and ward damage = 3k (or an equivalent per-cast +1 aether / +3 ward framing with no ceiling)"],["obj-4","BREAK.md proposes a minimal fix that removes the degeneracy while keeping the rune castable (dissipate/once-per-round clause, cost raised to >=1, or a capped aether gain) and does NOT propose simply deleting the rune or nerfing an unrelated rune"],["obj-5","BREAK.md is at most 450 words (whole file, wc -w)"]],subjective:[["sub-quality","Depth of the design critique",0.4],["sub-craft","Rigor of the degeneracy proof",0.3],["sub-reasoning","Reasoning quality",0.3]],weights:{objective:0.5,subjective:0.5}},
  "game-06c-boiler-overpressure":{category:"game-design",title:"Break the module set — find the seeded degenerate loop",objective:[["obj-1","BREAK.md identifies module D 'Boilertap' (by name or letter) as the degenerate/broken module"],["obj-2","BREAK.md states the loop is unbounded/infinite specifically because Boilertap costs 0 steam AND nets +1 steam per play with no once-per-tick/vent limiter — all three properties (cost 0, positive net steam, no limiter) must be cited"],["obj-3","BREAK.md shows the growth arithmetic explicitly: after k plays steam = starting + k and scald = 4k (or an equivalent per-play +1 steam / +4 scald framing with no ceiling)"],["obj-4","BREAK.md proposes a minimal fix that removes the degeneracy while keeping the module playable (vent/once-per-tick clause, cost raised to >=1, or a capped steam gain) and does NOT propose simply deleting the module or nerfing an unrelated module"],["obj-5","BREAK.md is at most 450 words (whole file, wc -w)"]],subjective:[["sub-quality","Depth of the design critique",0.4],["sub-craft","Rigor of the degeneracy proof",0.3],["sub-reasoning","Reasoning quality",0.3]],weights:{objective:0.5,subjective:0.5}},
  "game-07-branching-quest":{category:"game-design",title:"Branching quest graph with no soft-locks",objective:[["obj-1","Running the embedded reference validator with 'node validate.js quest.json' prints VALID and exits 0 (no unreachable nodes, no dangling choice ids, ending reachable, and NO soft-locked reachable node) — judge runs the validator exactly as embedded, does not hand-verify"],["obj-2","quest.json parses as valid JSON matching the schema (object with start, ending, and nodes array of {id, choices} with optional grants/requires arrays) when loaded with node, and has at least 8 nodes"],["obj-3","The validator prints a 'reachable N of M' line where N equals M (every declared node reachable from start) AND at least 2 nodes have 2+ entries in their choices array (genuine branch points)"],["obj-4","quest.json contains at least one node with a non-empty requires array whose required item appears in some node's grants array that lies on a forward path into the gate (the validator's VALID verdict already guarantees the gate is reachable; judge confirms such a requires-gate exists)"],["obj-5","STORY.md is at most 550 words (whole file, wc -w) and names the two distinct start-to-ending paths"]],subjective:[["sub-quality","Narrative branching quality",0.4],["sub-craft","Elegance of the gating and pacing",0.3],["sub-reasoning","Reasoning quality",0.3]],weights:{objective:0.5,subjective:0.5}},
