  "game-08-combo-engine":{category:"game-design",title:"Bounded-synergy proof for a stackable ability set",objective:[["obj-1","relics.json parses as valid JSON listing exactly 3 relic families, each with a name and an integer base bonus, loadable with node"],["obj-2","PROOF.md computes the WORST-CASE (output-maximizing) legal 3-relic loadout as the maximum over ALL size-3 multisets of the three families (not just same-family triples) and shows its total output <= 45 using the embedded diminishing-stack rule — judge recomputes the max over all multisets with node from relics.json base values and confirms it equals PROOF.md's stated worst-case number and is <= 45"],["obj-3","The worst-case total the judge recomputes over ALL legal multisets from relics.json is <= 45 AND the design admits at least one legal loadout reaching >= 30"],["obj-4","PROOF.md correctly applies the floor-division halving (e.g. shows a base-b family's three-copy contribution as b + floor(b/2) + floor(b/4)) rather than naive full-stacking"],["obj-5","PROOF.md is at most 500 words (whole file, wc -w)"]],subjective:[["sub-quality","Systems-design coherence",0.4],["sub-craft","Rigor and completeness of the bound proof",0.3],["sub-reasoning","Reasoning quality",0.3]],weights:{objective:0.7,subjective:0.3}},
  "game-08b-tonic-brewery":{category:"game-design",title:"Bounded-strength proof for a stackable tonic set",objective:[["obj-1","tonics.json parses as valid JSON listing exactly 3 tonic lines, each with a name and an integer base bonus, loadable with node"],["obj-2","PROOF.md computes the WORST-CASE (strength-maximizing) legal 3-dose batch as the maximum over ALL size-3 multisets of the three lines (not just same-line triples) and shows its total strength <= 42 using the embedded diminishing-stack rule — judge recomputes the max over all multisets with node from tonics.json base values and confirms it equals PROOF.md's stated worst-case number and is <= 42"],["obj-3","The worst-case total the judge recomputes over ALL legal multisets from tonics.json is <= 42 AND the design admits at least one legal batch reaching >= 27"],["obj-4","PROOF.md correctly applies the floor-division halving (e.g. shows a base-b line's three-dose contribution as b + floor(b/2) + floor(b/4)) rather than naive full-stacking"],["obj-5","PROOF.md is at most 500 words (whole file, wc -w)"]],subjective:[["sub-quality","Systems-design coherence",0.4],["sub-craft","Rigor and completeness of the bound proof",0.3],["sub-reasoning","Reasoning quality",0.3]],weights:{objective:0.7,subjective:0.3}},
