  "game-09-ev-economy":{category:"game-design",title:"Retune a chest economy to a target expected value",objective:[["obj-1","economy.json parses as valid JSON giving four tiers each with a fixed value (20/60/150/600) and a new probability, loadable with node, and the four probabilities sum to exactly 1.0 (within 1e-9)"],["obj-2","The retuned EV, recomputed by the judge as sum(prob*value) from economy.json, falls within [49.0, 51.0]"],["obj-3","All embedded constraints hold in economy.json: Legend probability in [0.02, 0.05], Common probability <= 0.70, Epic probability >= 0.05, every probability in [0,1]"],["obj-4","TUNING.md shows the post-retune EV arithmetic explicitly (the four prob*value products and their sum) and states it lands in [49.0, 51.0], and states the current EV was 80.5"],["obj-5","TUNING.md is at most 500 words (whole file, wc -w)"]],subjective:[["sub-quality","Economy-tuning judgment",0.4],["sub-craft","Clarity of the EV justification",0.3],["sub-reasoning","Reasoning quality",0.3]],weights:{objective:0.7,subjective:0.3}},
