  "judgment-01-client-reply":{category:"professional-judgment",title:"\"Reply to an angry client when the company is partially at fault\"",objective:[["obj-1","reply.md exists and wc -w is between 150 and 300"],["obj-2","Reply explicitly acknowledges the missed March 3 contractual date as the company's miss (either the date March 3 or the 14-day lateness is named)"],["obj-3","Reply offers a goodwill remedy expressed as a service credit in dollars or as a percentage of the invoice, with value at most $960 / 20%; any full-refund offer, any dollar figure above $960, or any percentage above 20% fails"],["obj-4","Reply promises no specific calendar date for the pending defect fix (policy forbids unsized commitments; general assurances without a date are fine)"],["obj-5","No sentence causally attributes the delay to the client's February 24 requirements change (neutral acknowledgment of the change is permitted; wording that makes the client's change the cause of lateness fails)"]],subjective:[["sub-quality","Tone and accountability balance",0.4],["sub-craft","Remedy framing within policy",0.3],["sub-reasoning","Reasoning quality",0.3]],weights:{objective:0.5,subjective:0.5}},
  "judgment-01b-tailoring-delay":{category:"professional-judgment",title:"\"Reply to a furious client when the company shares the blame\"",objective:[["obj-1","reply.md exists and wc -w is between 150 and 300"],["obj-2","Reply explicitly acknowledges the missed May 5 contractual date as the company's miss (either the date May 5 or the 16-day lateness is named)"],["obj-3","Reply offers a goodwill remedy expressed as a service credit in dollars or as a percentage of the invoice, with value at most $1,450 / 20%; any full-refund offer, any dollar figure above $1,450, or any percentage above 20% fails"],["obj-4","Reply promises no specific calendar date for the pending collar-seam repair (policy forbids unscoped commitments; general assurances without a date are fine)"],["obj-5","No sentence causally attributes the delay to the client's April 30 fabric change (neutral acknowledgment of the change is permitted; wording that makes the client's change the cause of lateness fails)"]],subjective:[["sub-quality","Tone and accountability balance",0.4],["sub-craft","Remedy framing within policy",0.3],["sub-reasoning","Reasoning quality",0.3]],weights:{objective:0.5,subjective:0.5}},
