  "reverse-03-relay-vm":{category:"reverse-engineering",title:"Trace the Relay Stack Machine",objective:[["obj-1","ANSWER.md states the emitted output is exactly 12 (an answer of 0 indicates the JNZ-pop trap was missed and is a hard fail on this check)"],["obj-2","ANSWER.md identifies the algorithm as the Euclidean GCD (any clear wording — 'gcd via repeated modulo', 'Euclid's algorithm', etc. — is accepted)"],["obj-3","ANSWER.md states the 91/63 variant emits exactly 7, and states exactly 19 instructions executed for the original 84/36 program per the counting rule stated in the test"],["obj-4","Judge runs `node vm.js` — it prints output 12 AND instruction count 19 for the embedded program; judge then edits the two PUSH immediates to 91 and 63 and re-runs — it prints output 7"],["obj-5","vm.js's own printed instruction count for the original program equals the 19 stated in ANSWER.md (the two must agree with each other and with the rubric's reference value)"]],subjective:[["sub-quality","Trace exposition",0.4],["sub-craft","Interpreter fidelity",0.3],["sub-reasoning","Reasoning quality",0.3]],weights:{objective:0.7,subjective:0.3}},
