  "reverse-05-signal-hut":{category:"reverse-engineering",title:"Recover the Handshake State Machine",objective:[["obj-1","Judge runs `node fsm.js` and it prints a transition table with exactly 4 states and exactly 8 defined transitions: CLOSED HELLO->AUTH_WAIT; AUTH_WAIT KEY->OPEN, AUTH_WAIT RESET->CLOSED; OPEN DATA->OPEN, OPEN PING->OPEN, OPEN BYE->DRAINING; DRAINING DATA->DRAINING, DRAINING RESET->CLOSED"],["obj-2","ANSWER.md states the minimum number of events to reach DRAINING from CLOSED is exactly 3, and states that all four states are reachable from CLOSED"],["obj-3","ANSWER.md classifies the three candidate sequences exactly: [HELLO,KEY,DATA,BYE,RESET] = ACCEPTED (ends in CLOSED); [HELLO,KEY,BYE,PING] = REJECTED at PING (invalid in DRAINING); [HELLO,DATA] = REJECTED at DATA (invalid in AUTH_WAIT)"],["obj-4","Judge feeds the embedded 12-line trace's event tokens (in order) back through `node fsm.js` starting at CLOSED and every ACCEPT/REJECT label and every named next-state reproduces exactly, with the session ending in state CLOSED"],["obj-5","fsm.js contains a generic event-driven simulator (a lookup keyed on current-state + event, rejects leaving state unchanged) rather than hardcoded per-question answers"]],subjective:[["sub-quality","State-table clarity",0.4],["sub-craft","Simulator generality",0.3],["sub-reasoning","Reasoning quality",0.3]],weights:{objective:0.7,subjective:0.3}},
  "reverse-05b-wash-bay-relay":{category:"reverse-engineering",title:"Recover the Wash-Bay Control Sequence",objective:[["obj-1","Judge runs `node fsm.js` and it prints a transition table with exactly 4 states and exactly 8 defined transitions: QUEUED PULSE->ARMED; ARMED SPIN->WASHING, ARMED SNAP->RINSING, ARMED DRIP->QUEUED; WASHING HOLD->WASHING, WASHING TAG->QUEUED; RINSING HOLD->RINSING, RINSING DRIP->QUEUED"],["obj-2","ANSWER.md states the minimum number of events to reach RINSING from QUEUED is exactly 2, and states that all four states are reachable from QUEUED"],["obj-3","ANSWER.md classifies the three candidate sequences exactly: [PULSE,SNAP,HOLD,DRIP,PULSE] = ACCEPTED (ends in ARMED); [PULSE,SNAP,SPIN] = REJECTED at SPIN (invalid in RINSING); [PULSE,HOLD] = REJECTED at HOLD (invalid in ARMED)"],["obj-4","Judge feeds the embedded 12-line trace's event tokens (in order) back through `node fsm.js` starting at QUEUED and every ACCEPT/REJECT label and every named next-state reproduces exactly, with the session ending in state QUEUED"],["obj-5","fsm.js contains a generic event-driven simulator (a lookup keyed on current-state + event, rejects leaving state unchanged) rather than hardcoded per-question answers"]],subjective:[["sub-quality","State-table clarity",0.4],["sub-craft","Simulator generality",0.3],["sub-reasoning","Reasoning quality",0.3]],weights:{objective:0.7,subjective:0.3}},
