  "sched-02-cross-zone-meeting-window":{category:"temporal-scheduling",title:"Single feasible cross-zone meeting window",objective:[["obj-1","Each participant's AT window is correct: P1 [420,900] (07:00-15:00), P2 [660,900] (11:00-15:00), P3 [480,960] (08:00-16:00), P4 [360,900] (06:00-15:00), minutes from AT-midnight"],["obj-2","The all-available intersection is stated as AT 11:00-15:00 (660 to 900 minutes)"],["obj-3","The valid 60-minute-meeting AT start range is stated as 11:00 to 14:00 inclusive (900 minus 60 = 840 minutes as the latest start)"],["obj-4","window.md or REASONING.md demonstrates the correct sign convention AT = local - offset, e.g. by showing P2's -180 offset shifting 08:00-12:00 local to 11:00-15:00 AT (prose-located)"],["obj-5","window.md correctly accounts for the meeting-end constraint by subtracting the 60-minute duration from the intersection end to get the latest start, rather than using the intersection start and end directly as the start range (prose-located)"]],subjective:[["sub-quality","Correctness of all four conversions and the final start range",0.4],["sub-craft","Legibility of the conversion table and boundary reasoning",0.3],["sub-reasoning","Reasoning quality",0.3]],weights:{objective:0.7,subjective:0.3}},
