  "uxcrit-02-search-feedback":{category:"ux-critique",title:"\"Critique a broken search-and-filter interaction\"",objective:[["obj-1","Has ## Problems, ## Severity, ## Fixes"],["obj-2","Mentions loading delay with no progress indication (spinner alone is not progress)"],["obj-3","Mentions oldest-first sort by default with no sort toggle or user preference"],["obj-4","Mentions filter triggering a full search re-run rather than narrowing in-place"],["obj-5","120–350 words (wc -w)"]],subjective:[["sub-quality","UX diagnostic quality",0.4],["sub-craft","Actionable fixes",0.3],["sub-reasoning","Reasoning quality",0.3]],weights:{objective:0.5,subjective:0.5}},
