  "uxcrit-02c-sort-filter-stale":{category:"ux-critique",title:"\"Critique a stale sort-and-filter interaction on a product listing\"",objective:[["obj-1","Has ## Problems, ## Severity, ## Fixes"],["obj-2","Mentions filter action resetting the active sort order silently without warning"],["obj-3","Mentions stale filter/sort chips displaying state that no longer matches the actual result ordering"],["obj-4","Mentions text search discarding previously applied filters without preserving or restoring them"],["obj-5","120–350 words (wc -w)"]],subjective:[["sub-quality","UX diagnostic quality",0.4],["sub-craft","Actionable fixes",0.3],["sub-reasoning","Reasoning quality",0.3]],weights:{objective:0.5,subjective:0.5}},
