  "uxcrit-03c-checkout-gotcha":{category:"ux-critique",title:"\"Critique a broken checkout flow with a pre-selected upsell trap\"",objective:[["obj-1","Has ## Problems, ## Severity, ## Fixes"],["obj-2","Mentions the pre-ticked add-on (protection plan) inflating the total without clear disclosure"],["obj-3","Mentions the identically-priced processing fee and protection plan creating visual conflation (user cannot distinguish the two charges)"],["obj-4","Mentions the order confirmation page being replaced by a marketing redirect with the confirmation details hidden behind a small link"],["obj-5","120–350 words (wc -w)"]],subjective:[["sub-quality","UX diagnostic quality",0.4],["sub-craft","Actionable fixes",0.3],["sub-reasoning","Reasoning quality",0.3]],weights:{objective:0.5,subjective:0.5}},
