  "writing-11-ghostwriter-voice-fingerprint":{category:"writing",title:"\"Ghostwriting to a measurable voice fingerprint\"",objective:[["obj-1","entry.md opens with a one-word first paragraph (the first paragraph, i.e. the text before the first blank line, is a single word), matching the fingerprint"],["obj-2","entry.md contains zero semicolons and exactly one em-dash ('—'), verified by scanning the text"],["obj-3","entry.md mean sentence length is under 12 words: total word count divided by the number of sentence-final terminators among '.', '!', '?' — obj-6 independently verifies no abbreviations, decimals, or ellipses are present, so once obj-6 passes, every such mark counted here is guaranteed to be a genuine sentence end"],["obj-4","entry.md whole-file word count is between 150 and 180 inclusive, verified with wc -w"],["obj-5","entry.md is on the supplied topic (the neighborhood bakery closing) and does not lapse into long abstract sentimentality — sentences stay concrete and short per the fingerprint (prose-located check; ships 2-3 PASS + 2-3 FAIL example phrasings)"],["obj-6","entry.md contains zero abbreviation-shaped tokens (e.g. 'a.m.', 'Mr.', 'St.'), zero decimals, and zero ellipses — every '.', '!', '?' in the file is a genuine sentence-final terminator, verified by scanning the text for any period not preceded immediately by a capitalized single-letter/short honorific token or followed by a digit, and for any '...' sequence"]],subjective:[["sub-quality","Fidelity to the target voice (reads like a Halloran sample)",0.4],["sub-craft","Handling the sentiment-vs-terseness tension without breaking voice",0.3],["sub-reasoning","Reasoning quality",0.3]],weights:{objective:0.7,subjective:0.3}},
  "writing-11b-dockside-bait-shop-closing":{category:"writing",title:"\"Ghostwriting a dockside columnist's measurable voice fingerprint\"",objective:[["obj-1","entry.md opens with a two-word first paragraph (the first paragraph, i.e. the text before the first blank line, is exactly two words), matching the fingerprint"],["obj-2","entry.md contains zero colons and exactly two em-dashes ('—'), verified by scanning the text"],["obj-3","entry.md mean sentence length is under 11 words: total word count divided by the number of sentence-final terminators among '.', '!', '?' — obj-6 independently verifies no abbreviations, decimals, or ellipses are present, so once obj-6 passes, every such mark counted here is guaranteed to be a genuine sentence end"],["obj-4","entry.md whole-file word count is between 155 and 190 inclusive, verified with wc -w"],["obj-5","entry.md is on the supplied topic (the bait-and-tackle shop on the pier closing for good) and does not lapse into long abstract sentimentality — sentences stay concrete and short per the fingerprint (prose-located check; ships 2-3 PASS + 2-3 FAIL example phrasings)"],["obj-6","entry.md contains zero abbreviation-shaped tokens (e.g. 'a.m.', 'Mr.', 'St.'), zero decimals, and zero ellipses — every '.', '!', '?' in the file is a genuine sentence-final terminator, verified by scanning the text for any period not preceded immediately by a capitalized single-letter/short honorific token or followed by a digit, and for any '...' sequence"]],subjective:[["sub-quality","Fidelity to the target voice (reads like an Abernathy sample)",0.4],["sub-craft","Handling the sentiment-vs-terseness tension without breaking voice",0.3],["sub-reasoning","Reasoning quality",0.3]],weights:{objective:0.7,subjective:0.3}},
  "writing-11c-payphone-booth-fingerprint":{category:"writing",title:"\"Matching a ghostwriter's voice to a measurable fingerprint\"",objective:[["obj-1","entry.md closes with a one-word final paragraph (the last paragraph, i.e. the text after the last blank line, is a single word), matching the fingerprint"],["obj-2","entry.md contains zero colons and exactly one parenthetical aside (a single matched pair of parentheses), verified by scanning the text"],["obj-3","entry.md mean sentence length is under 11 words: total word count divided by the number of sentence-final terminators among '.', '!', '?' — obj-6 independently verifies no abbreviations, decimals, or ellipses are present, so once obj-6 passes, every such mark counted here is guaranteed to be a genuine sentence end"],["obj-4","entry.md whole-file word count is between 160 and 190 inclusive, verified with wc -w"],["obj-5","entry.md is on the supplied topic (the last payphone booth on Pilcher Street being removed) and does not lapse into long abstract sentimentality — sentences stay concrete and short per the fingerprint (prose-located check; ships 2-3 PASS + 2-3 FAIL example phrasings)"],["obj-6","entry.md contains zero abbreviation-shaped tokens (e.g. 'a.m.', 'Mr.', 'St.'), zero decimals, and zero ellipses — every '.', '!', '?' in the file is a genuine sentence-final terminator, verified by scanning the text for any period not preceded immediately by a capitalized single-letter/short honorific token or followed by a digit, and for any '...' sequence"]],subjective:[["sub-quality","Fidelity to the target voice (reads like a K. Solberg sample)",0.4],["sub-craft","Handling the sentiment-vs-terseness tension without breaking voice",0.3],["sub-reasoning","Reasoning quality",0.3]],weights:{objective:0.7,subjective:0.3}},
  "writing-12-assembly-manual":{category:"writing",title:"\"Assembly manual from an unordered parts-and-steps dump\"",objective:[["obj-1","manual.md presents the steps as a numbered ordered list whose sequence respects EVERY prerequisite in the frozen prerequisite list (base before side panels joined to it; side panels joined to base before backboard attached; shelf pins before top panel fixed; cam locks set before backboard attached) — judge checks each prerequisite pair holds in the given order; any ordering that satisfies all four pairs passes, the order need not be unique"],["obj-2","The bolt-to-joint assignments are correct: type-S bolts are used only for the cam locks and type-M bolts for the panel joints (side-to-base x2, top-to-side; the base-to-feet joint is bolt-free snap clips) — no step calls for type-M bolts at the cam locks or type-S bolts at a panel joint"],["obj-3","The manual accounts for all listed parts, and the total bolts named across the numbered steps reconciles to 12 type-M + 4 type-S = 16 (judge sums the quantities explicitly stated in the steps and confirms the total against the parts list)"],["obj-4","Every step is a single self-contained imperative instruction (starts with an action verb, references specific named parts) — no step bundles two independent actions ambiguously (prose-located check; ships 2-3 PASS + 2-3 FAIL example phrasings)"],["obj-5","manual.md whole-file word count is at most 350, verified with wc -w, and it contains a parts-list section plus the numbered steps"]],subjective:[["sub-quality","Instructional clarity and unambiguity of each step",0.4],["sub-craft","Sequencing correctness and completeness of the procedure",0.3],["sub-reasoning","Reasoning quality",0.3]],weights:{objective:0.7,subjective:0.3}},
